const lead = $json.body;

return {
  json: {
    full_name: lead.full_name || lead.name || "",
    email: lead.email || lead.email_address || "",
    phone: lead.phone || lead.phone_number || "",
    company: lead.company || "",
    subject: lead.subject || "",
    message: lead.message || "",
    lead_source: lead.lead_source || "Website",
    received_at: new Date().toISOString()
  }
};

const lead = $json;
const errors = [];

if (!lead.full_name) {
    errors.push("Full name is required.");
}

if (!lead.email) {
    errors.push("Email is required.");
}

const isValid = errors.length === 0;

return {
    json: {
        ...lead,
        is_valid: isValid,
        validation_errors: errors
    }
};

const lead = $json;

const record = {};

const now = new Date();
const prefix = "LF";

const isoDate = now.toISOString();
const dateOnly = isoDate.split("T")[0];
const dateStamp = dateOnly.replaceAll("-", "");
const randomPart = Math.random().toString(36).substring(2, 8).toUpperCase();
record.lead_id = `${prefix}-${dateStamp}-${randomPart}`;
record.status = "Needs Information";

record.full_name = lead.full_name;
record.email = lead.email;
record.phone = lead.phone;
record.company = lead.company;
record.subject = lead.subject;
record.message = lead.message;
record.lead_source = lead.lead_source;
record.follow_up_sent = false;
record.received_at = now.toISOString();
record.validation_errors= lead.validation_errors;
record.is_valid = lead.is_valid;
record.follow_up_date= "";
record.notes= "";
record.intent = "Pending Validation";
record.summary = "Missing required information.";
record.priority = "Pending";

return {
  json: record
};

const promptData = $json;

const MODEL = "openai/gpt-4.1-nano";

const systemPrompt = `
You are a professional Customer Support Assistant.

Your responsibility is to generate a friendly and professional follow-up message for customers who submitted an incomplete inquiry form.

The customer has already submitted a contact form. The workflow has already validated the submission and identified the missing information.

Use the provided missing_fields array as the source of truth.

Guidelines:

- Request ONLY the missing information.
- Do not ask for information that has already been provided.
- Do not mention fields that are not listed in missing_fields.
- Do not invent customer information.
- Maintain a warm, friendly, and enthusiastic tone while remaining professional.
- Keep the response concise and easy to understand.
 If the customer's full name is available, greet them using only their first name.
  Example:
  "Hello John,"

- If the customer's full name is missing, simply begin with:
  "Hello,"

- Never use greetings such as "Hi there", "Dear Customer", or "Dear Sir/Madam".

- Keep the greeting warm, professional, and natural.
- Encourage the customer to reply with the missing information.

Generate ONLY the body of the follow-up request.

Generate ONLY the body of the follow-up request.

IMPORTANT:

The follow_up_message must begin immediately with the request.

Do NOT include any greeting.

Do NOT begin with:
- Hello
- Hi
- Dear
- Greetings

Do NOT include:

- greetings
- salutations
- thank-you messages
- signatures
- company names
- email subjects

The workflow will automatically add the greeting, branding, and signature.

Return ONLY a valid JSON object.

Do not include markdown.
Do not include explanations.
Do not wrap the response in code blocks.

The JSON object must exactly match this structure:

{
  "next_step": "request_missing_information",
  "follow_up_message": ""
}
`;

const userPrompt = `
Business Name:
${promptData.business_name}

Customer Name:
${promptData.full_name}

Company:
${promptData.company}

Email:
${promptData.email}

Phone:
${promptData.phone}

Subject:
${promptData.subject}

Customer Message:
${promptData.message}

Missing Information:
${promptData.missing_fields.join(", ")}
`;

promptData.model = MODEL;
promptData.system_prompt = systemPrompt;
promptData.user_prompt = userPrompt;

promptData.messages = [
    {
        role: "system",
        content: systemPrompt
    },
    {
        role: "user",
        content: userPrompt
    }
];

return {
    json: promptData
};

const response = $json;
const originalLead = $('AI - Prepare Messages').first().json;

// Parse the AI response
const parsedResponse = JSON.parse(
    response.choices[0].message.content
);

// Return both the original lead data and the AI response
return {
    json: {
        ...originalLead,

        next_step: parsedResponse.next_step,
        follow_up_message: parsedResponse.follow_up_message
    }
};

const lead = $json;

const missingFields = [];

for (const error of lead.validation_errors) {

    if (error === "Email is required.") {
        missingFields.push("Email Address");
    }

    if (error === "Phone Number is required.") {
        missingFields.push("Phone Number");
    }

    if (error === "Subject is required.") {
        missingFields.push("Subject");
    }

    if (error === "Company is required.") {
        missingFields.push("Company");
    }

    if (error === "Message is required.") {
        missingFields.push("Message");
    }

    if (error === "Full name is required.") {
        missingFields.push("Full Name");
    }

}

const promptData = {
    ...lead,
    business_name: "LeadFlow AI",
    missing_fields: missingFields

};

return {
    json: promptData
};

const lead = $json;

if (lead.email) {
    lead.contact_method = "email";
} else if (lead.phone) {
    lead.contact_method = "sms";
} else {
    lead.contact_method = "none";
}

return {
    json: lead
};

const lead = $json;

// Email Subject
lead.email_subject =
`Additional Information Required | ${lead.business_name} | ${lead.lead_id}`;

// Greeting
const greeting = lead.full_name
    ? `Hello ${lead.full_name.split(" ")[0]},`
    : "Hello,";

// Build the complete branded email
lead.email_body = `${greeting}

Thank you for contacting ${lead.business_name}.

${lead.follow_up_message}

Once we receive the requested information, we'll continue reviewing your inquiry as quickly as possible.

If you have any questions, simply reply to this email and we'll be happy to assist you.

Best regards,

${lead.business_name}
Customer Support Team`;

return {
    json: lead
};

const lead = $json;

const MODEL = "openai/gpt-4.1-nano";

const systemPrompt = `
You are an AI Intake Assistant for LeadFlow AI.

Your job is to analyze customer inquiries and return structured information.

Tasks:

1. Identify the customer's primary intent.
2. Write a concise summary of the inquiry.
3. Assign a priority:
   - High
   - Normal
4. Generate ONLY the body of a professional acknowledgement message.

IMPORTANT:

The acknowledgement_message must begin immediately with the message.

Do NOT include:
- greetings
- salutations
- thank-you messages
- signatures
- company names
- email subjects

The workflow will automatically add the greeting, branding, and signature.

Return ONLY a valid JSON object.

Do not include markdown.
Do not include explanations.
Do not wrap the response in code blocks.

The JSON object must exactly match this structure:

{
  "intent": "",
  "summary": "",
  "priority": "",
  "acknowledgement_message": ""
}
`;

const userPrompt = `
Business Name:
LeadFlow AI

Customer Name:
${lead.full_name}

Company:
${lead.company}

Email:
${lead.email}

Phone:
${lead.phone}

Subject:
${lead.subject}

Customer Message:
${lead.message}
`;

return {
    json: {
        ...lead,
        model: MODEL,
        system_prompt: systemPrompt,
        user_prompt: userPrompt,
        messages: [
            {
                role: "system",
                content: systemPrompt
            },
            {
                role: "user",
                content: userPrompt
            }
        ]
    }
};

const response = $json;

const parsed = JSON.parse(
    response.choices[0].message.content
);

response.intent = parsed.intent;
response.summary = parsed.summary;
response.priority = parsed.priority;
response.acknowledgement_message =
    parsed.acknowledgement_message;

delete response.choices;

return {
    json: response
};

const lead = $json;

const firstName = lead.full_name
    ? lead.full_name.split(" ")[0]
    : "";

const greeting = firstName
    ? `Hello ${firstName},`
    : "Hello,";

lead.email_to = lead.email;

lead.email_subject =
    "We've Received Your Inquiry - LeadFlow AI";

lead.email_body = `
${greeting}

Thank you for contacting LeadFlow AI.

We've received your inquiry and our team is currently reviewing it.

We'll get back to you as soon as possible. If we need any additional information, we'll contact you.

We look forward to working with you.

Best regards,

LeadFlow AI
Customer Support Team
`;

return {
    json: lead
};

const emailText = $json.text || "";
const subject = $json.subject || "";

// ----------------------------
// Clean the customer's reply
// ----------------------------
const replyMarker = emailText.search(/\nOn .*[\r\n]+wrote:/);

const customerReply =
	replyMarker !== -1
		? emailText.substring(0, replyMarker).trim()
		: emailText.trim();

// ----------------------------
// Extract Lead ID from subject
// ----------------------------
const leadIdMatch = subject.match(/LF-\d{8}-[A-Z0-9]+/);

const leadId = leadIdMatch ? leadIdMatch[0] : null;

// ----------------------------
// Extract Customer Email
// ----------------------------
const customerEmail =
	$json.from?.value?.[0]?.address || "";

// ----------------------------
// Extract Customer Name
// ----------------------------
const customerName =
	$json.from?.value?.[0]?.name || "";

// ----------------------------
// Return prepared data
// ----------------------------
return {
	json: {
		...$json,
		customer_reply: customerReply,
		lead_id: leadId,
		customer_email: customerEmail,
		customer_name: customerName
	}
};

const lead = $json;

// Convert validation_errors into an array
let validationErrors = [];

try {
    validationErrors = JSON.parse(lead.validation_errors);
} catch (e) {
    validationErrors = [];
}

// Convert validation messages into clean field names
const missingFields = validationErrors.map(error => {
    switch (error) {
        case "Full name is required.":
            return "Full Name";

        case "Email is required.":
            return "Email";

        default:
            return error;
    }
});

// Build prompt
const prompt = `
You are an AI assistant that extracts missing customer information.

Missing Fields:
${missingFields.map(field => `- ${field}`).join("\n")}

Customer Reply:
${lead.customer_reply}

Instructions:

1. Read the customer's reply carefully.
2. Extract ONLY the missing fields.
3. Do NOT guess.
4. If a field is missing, return null.
5. Return ONLY valid JSON.

Example:

{
    "full_name": "John Smith"
}
`;

return {
    json: {
        ...lead,

        model: "openai/gpt-4.1-nano",

        messages: [
            {
                role: "user",
                content: prompt
            }
        ]
    }
};

// Get the AI JSON string
const aiResponse = $json.choices[0].message.content;

// Convert JSON string into object
const extractedData = JSON.parse(aiResponse);

// Determine if required fields are now complete
const fullName = extractedData.full_name || $json.full_name;

const isComplete = !!fullName;

return {
  json: {
    ...$json,
    ...extractedData,

    is_valid: isComplete,

    validation_errors: isComplete
        ? ""
        : $json.validation_errors,

    status: isComplete
        ? "Ready for Review"
        : "Needs Information",

    summary: isComplete
        ? "Customer supplied the missing information via email."
        : $json.summary,

    intent: isComplete
        ? "Sales Review"
        : $json.intent
  }
};

const lead = $input.first().json;
const customerReply = $('Merge Lead + Reply').first().json.customer_reply || '';

return {
  json: {
    ...lead,
    notification_type: "Recovered Lead",
    customer_reply: customerReply
  }
};
